// ---------------------------------------------------------------------------------------------
// Builders

fn ty(n: &str) -> String {
    format!("{NS}.modAction#{n}")
}

/// A forum owned by user 0, with user 1 admin and user 2 moderator (plus `extra` moderator
/// entries), `membership` and `policy`.
fn forum_with(membership: &str, policy: Value, extra: &[Value]) -> Forum {
    let mut mods = vec![
        json!({"did": user(1), "role": "admin"}),
        json!({"did": user(2), "role": "moderator"}),
    ];
    mods.extend(extra.iter().cloned());
    let decl = json!({
        "name": "Test forum",
        "membership": membership,
        "moderators": mods,
        "policy": policy,
    });
    Forum::new(decl, T0 + 30 * DAY)
}

fn forum(membership: &str, policy: Value) -> Forum {
    forum_with(membership, policy, &[])
}

/// `did`'s membership and the owner's grant (`#access{member}`): a seed (S ⊆ E).
fn grant(f: &mut Forum, did: &str) {
    f.membership(did);
    let a = json!({"$type": ty("access"), "level": "member"});
    f.mod_action(&user(0), false, did, None, a, None, None, 1)
        .unwrap();
}

/// A valid article by `author` at `minute`.
fn post(f: &mut Forum, author: &str, minute: i64) -> String {
    let uri = f.ranged_uri(author, "post", minute);
    let v = f.post_value(minute, 0, 0, 0, "A post");
    f.put(&uri, Kind::Post, v, true, Forum::seen(minute))
        .unwrap();
    uri
}

/// A comment value on `root` with `parent`, citing their current CIDs (or [`FOREIGN_CID`] for
/// a uri that is not a record yet).
fn comment_at(f: &mut Forum, uri: &str, root: &str, parent: Option<&str>, minute: i64) -> String {
    let rc = f.cid_of(root).unwrap_or(FOREIGN_CID).to_owned();
    let pc = parent.map(|p| (p.to_owned(), f.cid_of(p).unwrap_or(FOREIGN_CID).to_owned()));
    let pref = pc.as_ref().map(|(u, c)| (u.as_str(), c.as_str()));
    let v = f.comment_value(minute, (root, &rc), pref, "A comment", false);
    f.put(uri, Kind::Comment, v, true, Forum::seen(minute))
        .unwrap();
    uri.to_owned()
}

/// A comment by `author` on `root` under `parent` at `minute`.
fn comment(f: &mut Forum, author: &str, root: &str, parent: Option<&str>, minute: i64) -> String {
    let uri = f.comment_uri(author, root, minute);
    comment_at(f, &uri, root, parent, minute)
}

/// An opinion of `voter` on `subject` with the axes `axes` (a JSON object), citing its current
/// CID.
fn opinion(f: &mut Forum, voter: &str, subject: &str, axes: Value) -> String {
    let cid = f.cid_of(subject).unwrap().to_owned();
    let m: Map<String, Value> = axes.as_object().unwrap().clone();
    f.opinion(voter, subject, &cid, m, 0).unwrap()
}

fn vote(f: &mut Forum, voter: &str, subject: &str, karma: &str) -> String {
    opinion(f, voter, subject, json!({"karma": karma}))
}

/// A forum-scope modAction of `actor` on `subject`; positive actions cite its current CID.
fn act(f: &mut Forum, actor: &str, subject: &str, action: Value, minute: i64) -> String {
    let cid = f.cid_of(subject).map(str::to_owned);
    f.mod_action(
        actor,
        false,
        subject,
        cid.as_deref(),
        action,
        None,
        None,
        minute,
    )
    .unwrap()
}

/// An author-scope modAction.
fn author_act(f: &mut Forum, actor: &str, subject: &str, action: Value, minute: i64) -> String {
    let cid = f.cid_of(subject).map(str::to_owned);
    f.mod_action(
        actor,
        true,
        subject,
        cid.as_deref(),
        action,
        None,
        None,
        minute,
    )
    .unwrap()
}

/// A wikiRevision of `slug` by `author` with `parents` (`(uri, cid)`).
fn wiki_rev(
    f: &mut Forum,
    author: &str,
    slug: &str,
    minute: i64,
    parents: &[(&str, &str)],
) -> String {
    let uri = f.ranged_uri(author, "wikiRevision", minute);
    wiki_rev_at(f, &uri, slug, minute, parents)
}

fn wiki_rev_at(
    f: &mut Forum,
    uri: &str,
    slug: &str,
    minute: i64,
    parents: &[(&str, &str)],
) -> String {
    let mut m = f.base("wikiRevision", minute);
    m.insert("slug".into(), json!(slug));
    m.insert("name".into(), json!(slug));
    if !parents.is_empty() {
        let ps: Vec<Value> = parents
            .iter()
            .map(|(u, c)| json!({"uri": u, "cid": c}))
            .collect();
        m.insert("parents".into(), json!(ps));
    }
    f.put(
        uri,
        Kind::WikiRevision,
        Value::Object(m),
        true,
        Forum::seen(minute),
    )
    .unwrap();
    uri.to_owned()
}

/// The fold of every record of `f` under `q`, checked for builder slips (validity).
fn run(f: &Forum, q: &Query) -> ForumView {
    let input = f.input();
    let v = fold(&input, q);
    check_validity(f, &input, &v);
    v
}

fn comments_query(thread: &str, sort: CommentSort) -> Query {
    Query {
        thread: Some(thread.to_owned()),
        comments: Some(CommentQuery {
            thread: thread.to_owned(),
            sort,
        }),
        ..Query::default()
    }
}

fn posts_query(sort: PostSort) -> Query {
    Query {
        posts: Some(PostQuery {
            sort,
            filter: PostFilter::All,
            ..PostQuery::default()
        }),
        ..Query::default()
    }
}

fn states(v: &ForumView) -> &BTreeMap<String, State> {
    &v.visibility.as_ref().unwrap().states
}

fn displayed(v: &ForumView) -> &BTreeMap<String, State> {
    &v.visibility.as_ref().unwrap().displayed
}

fn comment_order(v: &ForumView) -> Vec<String> {
    v.orderings.as_ref().unwrap().comment_order.clone().unwrap()
}

fn post_order(v: &ForumView) -> Vec<String> {
    v.orderings.as_ref().unwrap().post_order.clone().unwrap()
}

fn status(v: &ForumView, uri: &str) -> ModStatus {
    v.mod_log
        .as_ref()
        .unwrap()
        .iter()
        .find(|e| e.uri == uri)
        .unwrap_or_else(|| panic!("{uri} is not in the mod log"))
        .status
}

fn sorted<const N: usize>(mut xs: [String; N]) -> [String; N] {
    xs.sort();
    xs
}

/// `B` + the upper-case base32 body: another spelling of the same CID (G2 accepts it).
fn upper(cid: &str) -> String {
    format!("B{}", cid[1..].to_ascii_uppercase())
}

