// ---------------------------------------------------------------------------------------------
// K versus KP

/// A cast in which KP and K differ (approval mode, so E = S, every user granted):
///
/// ```text
/// boosters b1..b12: K1 = KP = K = 0
/// t : up from b1..b10                       K1 10, KP 10, K 10
/// s1: up from b1..b11, strongDown from t    K1 10 (−1), KP 9 (−strong(10) = −2), K 9
/// v : up from b1..b8, strongUp from s1      K1 9, KP 8 + strong(K1 s1 = 10) = 10, K 8 + strong(KP s1 = 9) = 9
/// w : strongUp from v                       K1 1, KP strong(9) = 1, K strong(10) = 2
/// z : up from v (did(z) < did(w))           K1 1, KP 1, K 1
/// ```
///
/// Then each rule that reads K (the author gate, the react creator, the wiki canonical tie)
/// and each that reads KP (tag-vote power) disagrees with the other basis.
#[test]
fn k_and_kp_differ_and_each_rule_reads_its_own() {
    let policy = json!({
        "authorModeration": true,
        "tagCreation": "open",
        "gates": {
            "authorModPersonal": 2, "authorModFrontpage": 2,
            "reactCreate": 0, "reactSecond": 0, "reactAnti": 0,
            "createTag": 0, "wikiEdit": 0,
        },
    });
    let mut f = forum("approval", policy);
    let boosters: Vec<String> = (20..32).map(user).collect();
    let (t, s1, v, z, w) = (user(40), user(41), user(42), user(43), user(44));
    assert!(z < w);
    for d in boosters.iter().chain([&t, &s1, &v, &z, &w]) {
        grant(&mut f, d);
    }
    let pt = post(&mut f, &t, 10);
    let ps1 = post(&mut f, &s1, 11);
    let pv = post(&mut f, &v, 12);
    let pw = post(&mut f, &w, 13);
    let pz = post(&mut f, &z, 14);
    for b in &boosters[..10] {
        vote(&mut f, b, &pt, "up");
    }
    for b in &boosters[..11] {
        vote(&mut f, b, &ps1, "up");
    }
    vote(&mut f, &t, &ps1, "strongDown");
    for b in &boosters[..8] {
        vote(&mut f, b, &pv, "up");
    }
    vote(&mut f, &s1, &pv, "strongUp");
    vote(&mut f, &v, &pw, "strongUp");
    vote(&mut f, &v, &pz, "up");

    // the author gate (K): w hides a comment in w's own thread with K = 2 ≥ 2 > KP = 1
    let b12 = boosters[11].clone();
    let cw = comment(&mut f, &b12, &pw, None, 20);
    let hide = author_act(&mut f, &w, &cw, json!({"$type": ty("hide")}), 21);
    // the react creator (K): w (K 2) over z (K 1), although z has the smaller DID and equal KP
    for d in [&w, &z] {
        opinion(&mut f, d, &pt, json!({"reacts": [{"react": "insightful"}]}));
    }
    // the wiki canonical tie (K): two genesis revisions at depth 0
    let rz = wiki_rev(&mut f, &z, "t", 30, &[]);
    let rw = wiki_rev(&mut f, &w, "t", 31, &[]);
    assert!(rz < rw);
    // tag-vote power (KP): v's strongUp is power(KP 10) = 2, not power(K 9) = 1
    let pq = post(&mut f, &b12, 15);
    opinion(
        &mut f,
        &v,
        &pq,
        json!({"tags": [{"tag": "t", "value": "strongUp"}]}),
    );

    let view = run(&f, &Query::default());
    let k = view.karma.as_ref().unwrap();
    let cast = |d: &str| (k.k1_of(d), k.kp_of(d), k.k_of(d));
    assert_eq!(cast(&t), (10, 10, 10));
    assert_eq!(cast(&s1), (10, 9, 9));
    assert_eq!(cast(&v), (9, 10, 9));
    assert_eq!(cast(&w), (1, 1, 2));
    assert_eq!(cast(&z), (1, 1, 1));

    assert_eq!(status(&view, &hide), ModStatus::Effective);
    assert_eq!(
        states(&view)[&cw],
        State::Hidden(HiddenReason::AuthorModerated)
    );
    let r = &view.reacts.as_ref().unwrap()[&pt];
    assert_eq!(r.len(), 1);
    assert_eq!(r[0].creator, w);
    assert_eq!(r[0].supporters, BTreeSet::from([w.clone(), z.clone()]));
    let wiki = view.wiki.as_ref().unwrap();
    assert_eq!(wiki.pages["t"].canonical.as_deref(), Some(rw.as_str()));
    assert_eq!(wiki.rel[&pq]["t"], 2);
    assert!(wiki.applies[&pq].contains("t"));
}

/// §13.3 `own(p, s) = max(1, small(max(KP, 0)))` reads KP, not K. `small` changes only at
/// 1,000, so the cast puts the author's KP and K on either side of it (default `pairCap` 25):
///
/// ```text
/// boosters b1..b40: K1 = KP = K = 0
/// t : up from b1..b10                               K1 10, KP 10, K 10
/// s1: up from b1..b11, strongDown from t            K1 10, KP 9, K 9
/// a : 998 ups from b1..b40 on a's 25 posts          KP 998 + strong(K1 s1 = 10) = 1000
///     (at most 25 per booster), strongUp from s1     K  998 + strong(KP s1 = 9)  = 999
/// ```
///
/// a's own tag on a's post weighs small(1000) = 2 (small(999) would be 1).
#[test]
fn own_tag_weight_reads_kp() {
    let mut f = forum("approval", json!({}));
    let boosters: Vec<String> = (100..140).map(user).collect();
    let (t, s1, a) = (user(40), user(41), user(42));
    for d in boosters.iter().chain([&t, &s1, &a]) {
        grant(&mut f, d);
    }
    let pt = post(&mut f, &t, 10);
    let ps1 = post(&mut f, &s1, 11);
    for b in &boosters[..10] {
        vote(&mut f, b, &pt, "up");
    }
    for b in &boosters[..11] {
        vote(&mut f, b, &ps1, "up");
    }
    vote(&mut f, &t, &ps1, "strongDown");
    // a's 25 posts, the first tagged `t`
    let pa: Vec<String> = (0..25)
        .map(|i| {
            let uri = f.ranged_uri(&a, "post", 20 + i);
            let v = f.post_value(20 + i, 0, u8::from(i == 0), 0, "A post");
            f.put(&uri, Kind::Post, v, true, Forum::seen(20 + i))
                .unwrap();
            uri
        })
        .collect();
    let mut ups = 0;
    for b in &boosters {
        for p in &pa {
            if ups < 998 {
                vote(&mut f, b, p, "up");
                ups += 1;
            }
        }
    }
    vote(&mut f, &s1, &pa[1], "strongUp");

    let view = run(&f, &Query::default());
    let k = view.karma.as_ref().unwrap();
    let cast = |d: &str| (k.kp_of(d), k.k_of(d));
    assert_eq!(cast(&t), (10, 10));
    assert_eq!(cast(&s1), (9, 9));
    assert_eq!(cast(&a), (1000, 999));
    assert_eq!(view.wiki.as_ref().unwrap().rel[&pa[0]]["t"], 2);
}

