// §13 wiki and tags

fn wiki_forum() -> Forum {
    forum(
        "approval",
        json!({"tagCreation": "open", "gates": {"createTag": 0, "wikiEdit": 0}}),
    )
}

/// §13.2 history: at a merge revision whose two parents have equal depth, the history follows
/// the smallest uri.
#[test]
fn wiki_history_tie_takes_the_smallest_uri() {
    let mut f = wiki_forum();
    let owner = user(0);
    let r1 = wiki_rev(&mut f, &owner, "h", 10, &[]);
    let r2 = wiki_rev(&mut f, &owner, "h", 11, &[]);
    let (c1, c2) = (
        f.cid_of(&r1).unwrap().to_owned(),
        f.cid_of(&r2).unwrap().to_owned(),
    );
    // list the greater uri first, so that the tie is not decided by array order
    let r3 = wiki_rev(&mut f, &owner, "h", 12, &[(&r2, &c2), (&r1, &c1)]);
    let v = run(&f, &Query::default());
    let page = &v.wiki.as_ref().unwrap().pages["h"];
    assert!(r1 < r2);
    assert_eq!(page.canonical.as_deref(), Some(r3.as_str()));
    assert_eq!(page.candidates[&r3].depth, 1);
    assert_eq!(page.history, [r3, r1]);
    assert_eq!(page.unmerged, 0);
}

/// §13.2 "ancestor altered" (NOTES 56): a uri listed twice in `parents`, once with an old CID
/// and once with the current one, marks the edge.
#[test]
fn wiki_duplicate_parent_entries_mark_the_edge_altered() {
    let mut f = wiki_forum();
    let owner = user(0);
    let r1 = wiki_rev(&mut f, &owner, "d", 10, &[]);
    let c1 = f.cid_of(&r1).unwrap().to_owned();
    let r2 = wiki_rev(&mut f, &owner, "d", 11, &[(&r1, FOREIGN_CID), (&r1, &c1)]);
    let r3 = wiki_rev(&mut f, &owner, "d", 12, &[(&r1, &c1), (&r1, &c1)]);
    let v = run(&f, &Query::default());
    let page = &v.wiki.as_ref().unwrap().pages["d"];
    assert_eq!(page.candidates[&r2].altered, BTreeSet::from([r1.clone()]));
    assert_eq!(page.candidates[&r2].parents, BTreeSet::from([r1.clone()]));
    assert!(page.candidates[&r3].altered.is_empty());
}

/// §13.2 (`limits.md` `WIKI_WALK_MAX`): 1,000 revisions fit; with 1,001 the page keeps the
/// 1,000 with the greatest (TID, then smallest uri) and is `partial`. The two lowest revisions
/// share a TID, so the one with the greater uri is the one dropped.
#[test]
fn wiki_page_cap_at_1000_and_1001() {
    let mut f = wiki_forum();
    let owner = user(0);
    let mut uris = Vec::new();
    for i in 0..999 {
        uris.push(wiki_rev(&mut f, &owner, "cap", 10 + i, &[]));
    }
    let tid = Tid::from_parts(u64::try_from(T0 + MINUTE).unwrap(), 0)
        .unwrap()
        .as_str()
        .to_owned();
    let low_a = format!("at://{}/{NS}.wikiRevision/{}-{tid}", user(1), f.fk);
    let low_b = format!("at://{}/{NS}.wikiRevision/{}-{tid}", user(2), f.fk);
    assert!(low_a < low_b);
    wiki_rev_at(&mut f, &low_a, "cap", 1, &[]);
    let at_cap = f.input();
    wiki_rev_at(&mut f, &low_b, "cap", 1, &[]);

    let v = fold(&at_cap, &Query::default());
    let page = &v.wiki.as_ref().unwrap().pages["cap"];
    assert!(!page.partial);
    assert_eq!(page.candidates.len(), 1000);

    let v = run(&f, &Query::default());
    let page = &v.wiki.as_ref().unwrap().pages["cap"];
    assert!(page.partial);
    assert_eq!(page.candidates.len(), 1000);
    assert!(page.candidates.contains_key(&low_a));
    assert!(!page.candidates.contains_key(&low_b));
    assert!(uris.iter().all(|u| page.candidates.contains_key(u)));
}

/// §13.3: tag-vote entries pass OP3 before OP4, so `[{t, up}, {t, superUp}]` is a vote of +1
/// for t (the unknown value is discarded first), not a conflict.
#[test]
fn tag_votes_op3_before_op4() {
    let mut f = forum("approval", json!({}));
    let (owner, admin) = (user(0), user(1));
    let p = post(&mut f, &admin, 10);
    let tags = json!({"tags": [{"tag": "t", "value": "up"}, {"tag": "t", "value": "superUp"}]});
    opinion(&mut f, &owner, &p, tags);
    let v = run(&f, &Query::default());
    assert_eq!(v.wiki.as_ref().unwrap().rel[&p]["t"], 1);
}

