// §0.4 CIDs

/// §0.4: CIDs compare by their canonical string form, so `B` + upper-case base32 (which G2
/// accepts) names the same version: a positive assertion counts, a vote is not "earlier", a
/// wiki parent is not "altered", a `#tag.head` applies, and two equal heads spelled differently
/// agree instead of conflicting.
#[test]
fn cid_spellings_compare_by_canonical_form() {
    let second_admin = json!({"did": user(3), "role": "admin"});
    let mut f = forum_with(
        "approval",
        json!({"tagCreation": "open", "gates": {"createTag": 0, "wikiEdit": 0}}),
        &[second_admin],
    );
    let (owner, admin, admin2, a) = (user(0), user(1), user(3), user(4));
    grant(&mut f, &a);
    let p = post(&mut f, &a, 10);
    let pc = upper(f.cid_of(&p).unwrap());
    let tier = f
        .mod_action(
            &owner,
            false,
            &p,
            Some(&pc),
            json!({"$type": ty("tier"), "tier": "frontpage"}),
            None,
            None,
            20,
        )
        .unwrap();
    let mut axes = Map::new();
    axes.insert("karma".into(), json!("up"));
    f.opinion(&owner, &p, &pc, axes, 0).unwrap();
    let r1 = wiki_rev(&mut f, &owner, "w", 30, &[]);
    let c1 = upper(f.cid_of(&r1).unwrap());
    let r2 = wiki_rev(&mut f, &owner, "w", 31, &[(&r1, &c1)]);
    // two rank-2 heads naming r1, one spelled upper case: they agree
    let canonical_c1 = f.cid_of(&r1).unwrap().to_owned();
    for (actor, cid) in [(&admin, &c1), (&admin2, &canonical_c1)] {
        f.mod_action(
            actor,
            false,
            "tag:w",
            None,
            json!({"$type": ty("tag"), "head": {"uri": r1, "cid": cid}}),
            None,
            None,
            40,
        )
        .unwrap();
    }
    let v = run(&f, &Query::default());
    assert_eq!(status(&v, &tier), ModStatus::Effective);
    assert_eq!(v.tiers[&p], Tier::Frontpage);
    assert!(!v.mod_queue.iter().any(|q| matches!(q, QueueItem::Stale(_))));
    let s = &v.scores.as_ref().unwrap()[&p];
    assert_eq!((s.earlier, s.weighted), (0, 1));
    let page = &v.wiki.as_ref().unwrap().pages["w"];
    assert!(page.candidates[&r2].altered.is_empty());
    assert!(v.moderation.conflicts.is_empty());
    // the head names r1 although r2 is deeper
    assert_eq!(page.canonical.as_deref(), Some(r1.as_str()));
}

