// §11 step 6 versions; §11 edited; §1.2 digest

/// §11 step 6: a comment whose `root.cid` (or `parent.cid`) is not its target's current CID is
/// "on revision n" (the snapshot of the target's n-th `op: update` revision) or "on an
/// unavailable version".
#[test]
fn comment_versions_name_revisions() {
    let mut f = forum("approval", json!({}));
    let (a, b) = (user(3), user(4));
    grant(&mut f, &a);
    grant(&mut f, &b);
    let p = post(&mut f, &a, 10);
    let v1 = f.get(&p).unwrap().value.clone();
    let cid1 = f.cid_of(&p).unwrap().to_owned();
    let mut v2 = f.post_value(10, 0, 0, 0, "A post, edited");
    v2["updatedAt"] = json!(at(20));
    f.update(&p, v2.clone());
    f.revision(&a, &p, &v1, 20);
    let cid2 = f.cid_of(&p).unwrap().to_owned();
    let mut v3 = f.post_value(10, 0, 0, 0, "A post, edited twice");
    v3["updatedAt"] = json!(at(30));
    f.update(&p, v3);
    f.revision(&a, &p, &v2, 30);
    let cid3 = f.cid_of(&p).unwrap().to_owned();
    let on = |f: &mut Forum, root_cid: &str, parent: Option<(&str, &str)>, minute: i64| {
        let uri = f.comment_uri(&b, &p, minute);
        let v = f.comment_value(minute, (&p, root_cid), parent, "A comment", false);
        f.put(&uri, Kind::Comment, v, true, Forum::seen(minute))
            .unwrap();
        uri
    };
    let c1 = on(&mut f, &cid1, None, 40);
    let c2 = on(&mut f, &cid2, None, 41);
    let c3 = on(&mut f, &cid3, None, 42);
    let c4 = on(&mut f, FOREIGN_CID, None, 43);
    let c5 = on(&mut f, &upper(&cid1), None, 44);
    let c1_cid = f.cid_of(&c1).unwrap().to_owned();
    let c6 = on(&mut f, &cid3, Some((&c1, FOREIGN_CID)), 45);
    let c7 = on(&mut f, &cid3, Some((&c1, &c1_cid)), 46);
    let v = run(&f, &Query::default());
    assert!(v.edited.contains(&p));
    assert_eq!(v.revisions[&p].len(), 2);
    let root = |n| CommentVersions {
        root: Some(n),
        parent: None,
    };
    assert_eq!(v.versions.get(&c1), Some(&root(Version::Revision(1))));
    assert_eq!(v.versions.get(&c2), Some(&root(Version::Revision(2))));
    assert_eq!(v.versions.get(&c3), None);
    assert_eq!(v.versions.get(&c4), Some(&root(Version::Unavailable)));
    assert_eq!(v.versions.get(&c5), Some(&root(Version::Revision(1))));
    assert_eq!(
        v.versions.get(&c6),
        Some(&CommentVersions {
            root: None,
            parent: Some(Version::Unavailable),
        })
    );
    assert_eq!(v.versions.get(&c7), None);
}

/// §11 "Edited" (the `[edited]` badge): a `createdAt` before 1970 has no µs, and counts as
/// earlier than any `updatedAt`.
#[test]
fn created_before_1970_with_updated_at_is_edited() {
    let mut f = forum("approval", json!({}));
    let a = user(1);
    let mut uris = Vec::new();
    for updated in [true, false] {
        let uri = f.ranged_uri(&a, "post", 10);
        let mut v = f.post_value(10, 0, 0, 0, "A post");
        v["createdAt"] = json!("1969-12-31T00:00:00.000Z");
        if updated {
            v["updatedAt"] = json!(at(20));
        }
        f.put(&uri, Kind::Post, v, true, Forum::seen(10)).unwrap();
        uris.push(uri);
    }
    let v = run(&f, &Query::default());
    assert!(v.edited.contains(&uris[0]));
    assert!(!v.edited.contains(&uris[1]));
}

/// §1.2: `obs` is outside the digest, yet `t_decl`'s future clamp reads `t_obs(decl)`, so two
/// inputs with equal digests can give an item that is not future-dated different `t_rank`s.
#[test]
fn digest_leaves_out_obs_which_moves_t_decl() {
    let mut f = forum("approval", json!({}));
    let a = user(1);
    // a post claimed (and keyed) 5 minutes before T0, first seen a minute after T0
    let early = T0 - 5 * MINUTE;
    let tid = Tid::from_parts(u64::try_from(early).unwrap(), 0).unwrap();
    let p = format!("at://{a}/{NS}.post/{}-{}", f.fk, tid.as_str());
    let mut pv = f.post_value(0, 0, 0, 0, "A post");
    pv["createdAt"] = json!("2025-12-31T23:55:00.000Z");
    f.put(&p, Kind::Post, pv, true, T0 + MINUTE).unwrap();
    let at_obs = |decl_obs: i64| {
        let mut j = f.json(&|_| true);
        for o in j["obs"].as_array_mut().unwrap() {
            if o["uri"] == json!(f.uri) {
                o["us"] = json!(decl_obs);
            }
        }
        FoldInput::from_vector_json(&j).unwrap()
    };
    let (x, y) = (at_obs(T0), at_obs(T0 - 10 * MINUTE));
    let (vx, vy) = (fold(&x, &Query::default()), fold(&y, &Query::default()));
    assert_eq!(vx.input_digest, vy.input_digest);
    assert_eq!((vx.t_decl, vy.t_decl), (T0, T0 - 10 * MINUTE));
    assert!(!vx.times[&p].future && !vy.times[&p].future);
    assert_eq!((vx.times[&p].t_rank, vy.times[&p].t_rank), (T0, early));
}

// ---------------------------------------------------------------------------------------------
// §1.1 malformed inputs; §20.1 item 43

/// §1.1, §20.1 item 25: the fold rejects a malformed input instead of folding it.
#[test]
fn malformed_inputs_are_rejected() {
    let mut f = forum("approval", json!({}));
    let (owner, admin) = (user(0), user(1));
    let p = post(&mut f, &admin, 10);
    vote(&mut f, &owner, &p, "up");
    let gone = f.ranged_uri(&admin, "post", 20);
    let base = f.json(&|_| true);
    let ok = |j: &Value| fold_view(&FoldInput::from_vector_json(j).unwrap(), &Query::default());
    assert!(ok(&base).is_ok());

    // a uri in both records and absent (an opinion names it)
    let mut j = base.clone();
    j["absent"] = json!([p]);
    assert!(ok(&j).is_err());
    // an absent uri that no opinion names
    let mut j = base.clone();
    j["absent"] = json!([gone]);
    assert!(ok(&j).is_err());
    // a record outside the input's sets: a membership whose rkey is not fk, a post outside the
    // fk range
    for uri in [
        format!("at://{admin}/{NS}.membership/self"),
        format!("at://{admin}/{NS}.post/3kabcdefghij2"),
    ] {
        let mut j = base.clone();
        let mut recs = j["records"].as_array().unwrap().clone();
        recs.push(json!({"uri": uri, "cid": FOREIGN_CID, "value": {"$type": "x"}}));
        recs.sort_by(|a, b| a["uri"].as_str().cmp(&b["uri"].as_str()));
        j["records"] = json!(recs);
        assert!(ok(&j).is_err(), "{uri}");
    }
    // an invalid declaration (FO4: an integer out of range)
    let mut j = base.clone();
    j["decl"]["value"]["policy"] = json!({"karma": {"pairCap": -1}});
    assert!(ok(&j).is_err());
    // algorithmIds: equal to the effective IDs (an unknown moderation ID falls back to mod/1),
    // or the input is malformed
    let ids = json!({"moderation": "mod/1", "karma": "karma/1", "ranking": "magic/1", "reactPalette": "default/1"});
    let mut j = base.clone();
    j["algorithmIds"] = ids.clone();
    assert!(ok(&j).is_ok());
    j["decl"]["value"]["policy"] = json!({"moderation": "mod/9"});
    let v = ok(&j).unwrap();
    assert!(v.newer_rules_banner);
    j["algorithmIds"]["moderation"] = json!("mod/9");
    assert!(ok(&j).is_err());
    let mut j = base;
    j["algorithmIds"] = ids;
    j["algorithmIds"]["ranking"] = json!("magic/2");
    assert!(ok(&j).is_err());
}

/// §20.1 item 43 (`data-model.md` MA2): a modAction under the reserved `^FK-TID$` key is checked
/// against G1–G10 and MA10–MA12 only, so a subject that would fail MA3 (another forum's fk)
/// leaves it valid and `reserved/unknown`.
#[test]
fn reserved_key_record_skips_ma3() {
    let mut f = forum("approval", json!({}));
    let owner = user(0);
    let other = keys::fk(&format!("at://{owner}/{NS}.forum/elsewhere")).unwrap();
    let subject = format!("at://{}/{NS}.post/{other}-3kabcdefghij2", user(4));
    let rkey = f.ranged_uri(&owner, "modAction", 10);
    let mut m = f.base("modAction", 10);
    m.insert("subject".into(), json!(subject));
    m.insert("action".into(), json!({"$type": ty("hide")}));
    f.put(
        &rkey,
        Kind::ModForum,
        Value::Object(m),
        true,
        Forum::seen(10),
    )
    .unwrap();
    let v = run(&f, &Query::default());
    assert!(!v.raw.invalid.contains_key(&rkey));
    assert_eq!(status(&v, &rkey), ModStatus::ReservedUnknown);
}

// ---------------------------------------------------------------------------------------------
// CO5 (§20.1 item 51)

/// §20.1 item 51 (pinned by `visibility/visibility.json` `co5-invalid-root-is-a-missing-root`,
/// `karma/staged.json` `co5-invalid-root-opinions-count`, `thread/thread.json`
/// `root-names-another-forum`): when the author of a root post edits its `forum` to name another
/// forum (invalid by G9), CO5 does not compare it. The post is Excluded and becomes a `Missing`
/// root; its comments stay in the thread under the placeholder, keep their own states and
/// scores, and the votes on them keep counting. The outsider author cannot remove the thread.
#[test]
fn co5_edit_of_the_root_forum_keeps_the_thread() {
    let mut f = forum("open", json!({"display": {"newUsers": "collapse"}}));
    let (owner, admin, moder, member, outsider) = (user(0), user(1), user(2), user(4), user(9));
    grant(&mut f, &member);
    f.membership(&outsider);
    let p = post(&mut f, &outsider, 10);
    let c4 = comment(&mut f, &member, &p, None, 20);
    let c2 = comment(&mut f, &moder, &p, None, 21);
    vote(&mut f, &owner, &c4, "up");
    vote(&mut f, &admin, &c2, "up");
    let before = run(&f, &Query::default());
    assert_eq!(
        states(&before)[&p],
        State::Collapsed(CollapseReason::NewUser)
    );
    assert_eq!(states(&before)[&c4], State::Visible);
    assert_eq!(states(&before)[&c2], State::Visible);
    let k = before.karma.as_ref().unwrap();
    assert_eq!((k.k_of(&member), k.k_of(&moder)), (1, 1));

    let invalid = f.post_value(10, 0, 0, 2, "A post");
    f.update(&p, invalid);
    f.recs.iter_mut().find(|r| r.uri == p).unwrap().valid = false;
    let after = run(&f, &Query::default());
    assert_eq!(states(&after)[&p], State::Excluded);
    assert_eq!(states(&after)[&c4], State::Visible);
    assert_eq!(states(&after)[&c2], State::Visible);
    let k = after.karma.as_ref().unwrap();
    assert_eq!(k.counting.len(), 2);
    assert_eq!((k.k_of(&member), k.k_of(&moder)), (1, 1));
    let (was, scores) = (
        before.scores.as_ref().unwrap(),
        after.scores.as_ref().unwrap(),
    );
    assert_eq!(scores[&c4], was[&c4]);
    assert_eq!(scores[&c2], was[&c2]);
    assert_eq!((scores[&c4].weighted, scores[&c2].weighted), (1, 1));
    assert!(!scores.contains_key(&p));
    let t = &after.threads[&p];
    assert!(t.root_missing);
    assert_eq!(t.parent[&c4], Parent::Root);
    assert_eq!(t.parent[&c2], Parent::Root);
    // the comments' lower bound is now t_decl (a Missing root's thread), not the post
    assert!(after.times.contains_key(&c4) && !after.times.contains_key(&p));
}

/// CO5 still compares a **valid** root: a valid root whose `forum` is not the comment's (which
/// needs a 60-bit fk collision, simulated here by a validity function that accepts the edited
/// root) excludes the thread's comments (V1), and the votes on them do not count (O2).
#[test]
fn co5_a_valid_root_naming_another_forum_excludes_its_comments() {
    use lessdugin_core::social::full::cx::lexicon_validity;
    use lessdugin_core::social::full::fold_view_with;
    let mut f = forum("open", json!({}));
    let (owner, member, author) = (user(0), user(4), user(5));
    grant(&mut f, &member);
    grant(&mut f, &author);
    let p = post(&mut f, &author, 10);
    let c = comment(&mut f, &member, &p, None, 20);
    vote(&mut f, &owner, &c, "up");
    let other = f.post_value(10, 0, 0, 2, "A post");
    f.update(&p, other);
    f.recs.iter_mut().find(|r| r.uri == p).unwrap().valid = false;
    let input = f.input();
    let collide = |u: &str, v: &Value| {
        if u == p {
            (true, None)
        } else {
            lexicon_validity(u, v)
        }
    };
    let v = fold_view_with(&input, NS, &collide, &Query::default()).unwrap();
    // the root itself is Excluded by V1 (x.forum ≠ F), and CO5 excludes the comment
    assert_eq!(states(&v)[&p], State::Excluded);
    assert_eq!(states(&v)[&c], State::Excluded);
    let k = v.karma.as_ref().unwrap();
    assert!(k.counting.is_empty());
    assert_eq!(k.k_of(&member), 0);
    // with the lexicon's validity the same root is invalid, a Missing root: the comment stays
    let v = run(&f, &Query::default());
    assert_eq!(states(&v)[&c], State::Visible);
    assert_eq!(v.karma.as_ref().unwrap().k_of(&member), 1);
}

// ---------------------------------------------------------------------------------------------
// §1.3 rule 3

/// §1.3 rule 3: `hot` uses `libm::pow`, pinned exactly; an upgrade must leave every bit pattern
/// unchanged. The rank vectors pin a few values; this pins 1,440 more (b, age, offsetHours,
/// exponentMilli) through a digest of their bit patterns, so a `libm` update that moves any of
/// them fails here, before it can reorder posts differently from the indexer.
#[test]
fn hot_bits_are_pinned() {
    use lessdugin_core::social::rank::hot;
    let now = T0 + 30 * DAY;
    let mut bits = Vec::new();
    for b in [1i64, 2, 7, 25, 100, 1234, 99_999, 1 << 40] {
        for age_min in [
            0i64, 1, 30, 59, 61, 180, 1439, 1441, 10_000, 129_599, 129_601, 1_000_000,
        ] {
            for offset in [1i64, 2, 24] {
                for exp in [1, 1150, 1800, 2500, 3333] {
                    let h = hot(b, now - age_min * MINUTE, now, offset, exp);
                    bits.extend_from_slice(&h.to_bits().to_be_bytes());
                }
            }
        }
    }
    assert_eq!(bits.len(), 8 * 8 * 12 * 3 * 5);
    let digest: String = lessdugin_atp::cid::sha256(&bits)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect();
    assert_eq!(
        digest, "6077f366982d782d6452b84b957a60e0dcbbfc850d575d8ae9d209db1e09ee40",
        "libm::pow changed a hot() bit pattern"
    );
}

/// The fold of a vector-style input projects `digestPreimage` from the input
/// ([`project_fold`]); the view does not keep the preimage.
#[test]
fn digest_preimage_is_projected_from_the_input() {
    let mut f = forum("approval", json!({}));
    let p = post(&mut f, &user(1), 10);
    let input = f.input();
    let v = fold(&input, &Query::default());
    let d = project_fold(&input, &v, "digestPreimage").unwrap();
    let d = d.as_str().unwrap();
    assert!(d.starts_with(&format!("{p}\u{0}")));
    assert!(d.contains("\ndecl\u{0}"));
    assert!(lessdugin_core::social::full::project(&v, "digestPreimage").is_err());
}
